#requires -Version 5.1
[CmdletBinding()]param()
$root='C:\ProgramData\BlueRidge\ActivationReports';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$d=Join-Path $root "activation-$env:COMPUTERNAME-$s";New-Item -ItemType Directory -Force -Path $d|Out-Null;Start-Transcript -Path (Join-Path $logs 'windows-activation-check.log') -Append|Out-Null
try{$products=Get-CimInstance SoftwareLicensingProduct -ErrorAction SilentlyContinue|Where-Object{$_.PartialProductKey -and $_.Name -match 'Windows'}|Select Name,Description,LicenseStatus,GracePeriodRemaining,PartialProductKey,ProductKeyChannel;$products|Export-Csv (Join-Path $d activation-products.csv) -NoTypeInformation;cscript.exe //Nologo "$env:SystemRoot\System32\slmgr.vbs" /xpr|Out-File (Join-Path $d expiration.txt);cscript.exe //Nologo "$env:SystemRoot\System32\slmgr.vbs" /dlv|Out-File (Join-Path $d detailed-license.txt);$map=@{0='Unlicensed';1='Licensed';2='OOB Grace';3='OOT Grace';4='Non-Genuine Grace';5='Notification';6='Extended Grace'};$products|ForEach-Object{Write-Host ("{0}: {1}" -f $_.Name,$map[[int]$_.LicenseStatus])};Write-Host "Activation report: $d" -ForegroundColor Green}finally{Stop-Transcript|Out-Null}
